package main

import (
	"fmt"
	"sync"
)

type Cache struct {
	sync.Mutex
	data map[string]int
}

func (c *Cache) Get(k string) int {
	c.Lock()
	defer c.Unlock()
	return c.data[k]
}

func main() {
	c := &Cache{data: map[string]int{"a": 1}}
	c.Lock() // a caller can lock it too
	c.Unlock()
	fmt.Println(c.Get("a"))
}

package main

import "fmt"

type Counter struct{ n int }

func (c Counter) Inc() { c.n++ }

type Incrementer interface{ Inc() }

func main() {
	var a Incrementer = &Counter{}
	var b Incrementer = Counter{}
	a.Inc()
	b.Inc()
	fmt.Println(a, b)
	c := Counter{}
	c.Inc()
	fmt.Println(c.n)
}
